            source=DataSource.PDF_INVOICE,
            metadata={"document_type": "invoice", "filename": original_filename},
        )

        return WebhookResponse(
            status="enqueued",
            message=f"Invoice PDF {original_filename} text extracted and enqueued",
            data_id=item_id,
        )

    except HTTPException:
