import ast as _ast

def extract_text(content):
    if isinstance(content, str):
        stripped = content.strip()
        if stripped.startswith('[') or stripped.startswith('{'):
            try:
                parsed = _ast.literal_eval(stripped)
                return extract_text(parsed)
            except (ValueError, SyntaxError):
                pass
        return content
    if isinstance(content, list):
        parts = []
        for block in content:
            if isinstance(block, dict):
                parts.append(block.get('text', str(block)))
            elif hasattr(block, 'text'):
                parts.append(str(block.text))
            else:
                parts.append(str(block))
        return '\n'.join(parts)
    if hasattr(content, 'text'):
        return str(content.text)
    return str(content)

# case 1: plain string
assert extract_text('hello') == 'hello'

# case 2: list of dicts
assert extract_text([{'type': 'text', 'text': '- line one'}]) == '- line one'

# case 3: list of dicts with extras
assert extract_text([{'type': 'text', 'text': '- line one', 'extras': {'sig': 'abc'}}]) == '- line one'

# case 4: stringified list (the bug the user hit)
s = str([{'type': 'text', 'text': '- <NAME_8> GmbH: services'}])
assert extract_text(s) == '- <NAME_8> GmbH: services', repr(extract_text(s))

# case 5: object with .text attribute
class Obj:
    text = '- from object'
assert extract_text(Obj()) == '- from object'

print('all cases pass')
